title:
// ❌ 멱등성 없음 — 렌더링 중에 외부 변수 변경
let count = 0
function Counter() {
  count++ // 렌더링마다 값이 달라짐
  return <div>{count}</div>
}

// ✅ 멱등성 있음 — 같은 입력, 같은 출력
function Counter({ value }) {
  return <div>{value}</div>
}

